import {isNRF52} from './unified-project.js';
export function installNRF52Keyboard({getProject,getSnapshot,showDialog,send,setPressed}){
 const button=document.createElement('button');button.id='nrf-keyboard';button.textContent='USB / BLE Klavye';button.title='nRF52840 sanal klavye alıcısı';document.getElementById('bluetooth-network').after(button);
 button.onclick=()=>{showDialog('nRF52840 · USB / BLE klavye alıcısı',`<div data-nrf-keyboard-panel><p>Firmware tuş raporlarını bu sanal alıcıya gönderir. Bilgisayarınıza tuş basılmaz; gerçek USB aygıtı veya Bluetooth radyo bağlantısı oluşturulmaz.</p><p>Projeler → <strong>nRF52840 · USB / BLE klavye</strong> örneğini açın, Çalıştır’a basın ve aşağıdaki alıcıları bağlayın. Devredeki A / B / Shift butonlarını kullanın.</p><div class="dialog-actions"><strong>Devre tuşları</strong><button data-kbd-key="keyA">A</button><button data-kbd-key="keyB">B</button><button data-kbd-key="keyShift">Shift</button></div><small>Bu tuşlar hazır örneğin gerçek tact/GPIO girişlerini değiştirir. Paneli kapatıp devredeki butonları da kullanabilirsiniz.</small>${['usb','ble'].map(t=>`<section style="border:1px solid #526273;padding:14px;margin:12px 0;border-radius:6px"><h3>${t==='usb'?'USB HID · sanal host':'Bluetooth LE HID · sanal GATT'}</h3><p data-kbd-status="${t}" role="status"></p><div class="dialog-actions"><button data-kbd-action="connect" data-transport="${t}">${t==='usb'?'USB bağla':'BLE bağlan'}</button><button data-kbd-action="disconnect" data-transport="${t}">Bağlantıyı kes</button><button data-kbd-action="caps" data-transport="${t}">Caps Lock</button><button data-kbd-action="clear" data-transport="${t}">Çıktıyı temizle</button></div>${t==='ble'?'<label><input type="checkbox" data-kbd-subscribe checked> Tuş bildirimlerine abone ol (CCCD)</label>':''}<label>Alınan metin<textarea data-kbd-text="${t}" readonly aria-label="${t==='usb'?'USB':'BLE'} alınan tuşlar" rows="3" style="width:100%;background:#101c28;color:#f2f6fa;padding:10px;font:18px monospace"></textarea></label><pre data-kbd-report="${t}" style="white-space:pre-wrap"></pre></section>`).join('')}<details><summary>Desteklenen kapsam ve API</summary><p>C17 <code>#include &lt;wirevo_keyboard.h&gt;</code>: USB/BLE begin, ready, report, release, leds ve end. 8 bayt rapor: modifier, 0, altı tuş usage kodu. US klavye düzeni; Ctrl/Alt/GUI ham olay olarak kaydedilir.</p><p>Wirevo’ya özgü sanal taşıma API’si; Nordic USBD/RADIO yazmaç sürücüsü, SoftDevice, ZMK/Zephyr veya tam TinyUSB desteği değildir. Eşleştirme/şifreleme, RF ve işletim sistemine klavye bağlantısı yoktur.</p><a href="./notices/NRF52-KEYBOARD.md" target="_blank">API, örnek ve sınırlar</a></details></div>`);
 const panel=document.querySelector('[data-nrf-keyboard-panel]');panel.querySelectorAll('[data-kbd-key]').forEach(b=>{const press=v=>{setPressed?.(b.dataset.kbdKey,v);b.setAttribute('aria-pressed',String(v));};b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(true);};b.onpointerup=()=>press(false);b.onpointercancel=()=>press(false);b.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();press(true);}};b.onkeyup=e=>{if(['Enter',' '].includes(e.key))press(false);};b.onblur=()=>press(false);});panel.querySelectorAll('[data-kbd-action]').forEach(b=>b.onclick=()=>{const t=b.dataset.transport,c=getSnapshot()?.keyboard?.[t],action=b.dataset.kbdAction;send({type:'keyboard',transport:t,action:action==='caps'?'leds':action,...(action==='caps'?{value:(c?.leds||0)^2}:{})});});panel.querySelector('[data-kbd-subscribe]').onchange=e=>send({type:'keyboard',transport:'ble',action:'subscribe',enabled:e.target.checked});render();};
 function render(){const available=isNRF52(getProject());button.hidden=!available;const panel=document.querySelector('[data-nrf-keyboard-panel]');if(!panel||!available)return;const k=getSnapshot()?.keyboard;for(const t of ['usb','ble']){const c=k?.[t];panel.querySelector(`[data-kbd-status="${t}"]`).textContent=!c?.initialized?'Firmware servisi henüz başlamadı.':c.connected?'Bağlı'+(t==='ble'?(c.subscribed?' · Bildirim açık':' · Bildirim kapalı'):' · Yapılandırma 1 · IN 0x81'):t==='ble'?'Reklam yayını hazır · '+c.name:'USB klavye hazır · alıcı bağlı değil';const text=panel.querySelector(`[data-kbd-text="${t}"]`);if(text.value!==(c?.text||''))text.value=c?.text||'';panel.querySelector(`[data-kbd-report="${t}"]`).textContent=c?`Rapor: ${c.report.map(x=>x.toString(16).padStart(2,'0')).join(' ')}\n${c.reports} rapor · Caps Lock ${c.leds&2?'açık':'kapalı'}\nSon olay: ${JSON.stringify(c.events.at(-1)||{})}`:'';for(const b of panel.querySelectorAll(`[data-transport="${t}"]`))b.disabled=b.dataset.kbdAction==='connect'?!c?.initialized||c.connected:['disconnect','caps'].includes(b.dataset.kbdAction)?!c?.connected:false;}const sub=panel.querySelector('[data-kbd-subscribe]');sub.checked=!!k?.ble?.subscribed;sub.disabled=!k?.ble?.connected;}
 return{render};
}
